// Serverless Booking Endpoint for Vercel / Netlify
// Generated by Ghost for kit-sm-79b6a9
module.exports = async (req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    return res.status(200).end();
  }

  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  try {
    const data = typeof req.body === 'string' ? JSON.parse(req.body) : (req.body || {});
    const { name, phone, email, date, time, service, party_size, notes, company_website } = data;

    // Honeypot check: reject bot submissions silently
    if (company_website) {
      return res.status(200).json({ status: 'ignored' });
    }

    const bookingPayload = {
      slug: "kit-sm-79b6a9",
      name: (name || '').slice(0, 120),
      contact: (email || phone || '').slice(0, 200),
      phone: (phone || '').slice(0, 50),
      date: (date || '').slice(0, 50),
      time: (time || '').slice(0, 50),
      service: (service || '').slice(0, 100),
      party_size: party_size || null,
      notes: (notes || '').slice(0, 1000),
      received_at: new Date().toISOString()
    };

    // Forward to Ghost CRM webhook if configured
    const webhookUrl = process.env.GHOST_CRM_WEBHOOK_URL;
    if (webhookUrl) {
      try {
        await fetch(webhookUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(bookingPayload)
        });
      } catch (fwdErr) {
        console.error('CRM booking forwarding error:', fwdErr);
      }
    }

    return res.status(200).json({
      status: 'confirmed',
      message: 'Booking request registered. Concierge confirmation will follow shortly.',
      booking: bookingPayload
    });
  } catch (err) {
    console.error('Booking submission error:', err);
    return res.status(500).json({ error: 'Internal server error' });
  }
};
